INSERT INTO workout_exercises (workout_id, sort_order, name, weight_text, pct_of_tm, target_reps, target_sets, target_rir_min, target_rir_max, comment, rest_seconds, program_key, role, pct_min, pct_max, example_kg_min, example_kg_max, target_rpe_min, target_rpe_max, is_optional, condition_code, exclude_from_tonnage, prescription) VALUES ((SELECT id FROM workouts WHERE program_key='v4:h2-1-b1'), 2, 'Ягодичный мост', NULL, NULL, '8', '1', NULL, NULL, 'Только при согласованной переносимости; выбранный режим заменяет, а не дополняет этот комплекс.
