INSERT INTO workouts (cycle_id, label, title, notes, sort_order, kind, cardio_zone, cardio_minutes, program_key, day_in_cycle, warmup_level, prescription, branches) VALUES ((SELECT id FROM cycles WHERE program_version='h2-v9-4.0' AND program_key='v4:h2-2'), 'B4', 'Зал B · Накопление I', 'Стимул создают рабочие повторения с запасом, а не дополнительный список жимов. Первые подходы легче последних.
Сначала симптомы/седация, затем готовность, страховка и разминка. Никаких автоматических медицинских уровней по проценту.
RPE — фактическая оценка запаса, не прогноз из килограммов. Разминка строится от выбранного рабочего веса и не превышает личного предела.
При нехватке времени: основной жим с полноценным отдыхом → одна тяга → остальная подсобка → необязательная ОФП.', 4, 'strength', NULL, NULL, 'v4:h2-2-b4', 8, 'normal', '{"id":"h2-2-b4","slot":"B4","day":8,"kind":"strength","title":"Зал B · Накопление I","duration":{"min":55,"max":75},"isRestDay":false,"isDeload":false,"isTaper":false,"isControl":false,"cardio":null,"warmupLevel":"normal","exercises":[{"id":"h2-2-b4-paused_bench_0","key":"paused_bench_0","name":"Жим лёжа с паузой","sets":"3","reps":"8","role":"primary_bench","percent":{"min":65.21739130434783,"max":65.21739130434783},"exampleKg":{"min":75,"max":75},"targetRpe":{"min":6,"max":7.5},"targetRir":null,"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":240,"notes":["Вес — стартовый пример при R=115, а не обязательное назначение. Фактический RPE важнее цифры.","До последнего сета при RPE около 7,5 снизить вес на 2,5–5 кг; при RPE 8 обычный основной жим закончить.","Одинаковое касание и пауза около секунды; без отказа и компенсации пропусков."],"afterControlLight":false,"progressionEligible":true},{"id":"h2-2-b4-incline_dumbbell_press","key":"incline_dumbbell_press","name":"Наклонный жим гантелей 15–30°","sets":"2","reps":"8–12","role":"chest_accessory","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":2,"max":3},"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":120,"notes":["Вес подбирать отдельно по запасу. После двух выполнений всех сетов на верхней границе повторов с целевым RIR — минимальный шаг; затем нижняя граница повторов.","Не переносить прибавку жима на гантели или блок. При боли прекратить провоцирующее упражнение."]},{"id":"h2-2-b4-chest_supported_row","key":"chest_supported_row","name":"Тяга с опорой грудью","sets":"2","reps":"10–12","role":"upper_back","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":2,"max":3},"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":120,"notes":["Вес подбирать отдельно по запасу. После двух выполнений всех сетов на верхней границе повторов с целевым RIR — минимальный шаг; затем нижняя граница повторов.","Не переносить прибавку жима на гантели или блок. При боли прекратить провоцирующее упражнение."]},{"id":"h2-2-b4-lat_pulldown","key":"lat_pulldown","name":"Верхний блок","sets":"3","reps":"8–12","role":"back_accessory","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":2,"max":3},"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":120,"notes":["Вес подбирать отдельно по запасу. После двух выполнений всех сетов на верхней границе повторов с целевым RIR — минимальный шаг; затем нижняя граница повторов.","Не переносить прибавку жима на гантели или блок. При боли прекратить провоцирующее упражнение."]},{"id":"h2-2-b4-lateral_raise","key":"lateral_raise","name":"Подъём рук в стороны","sets":"2","reps":"12–20","role":"shoulder_accessory","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":3,"max":3},"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":60,"notes":["Вес подбирать отдельно по запасу. После двух выполнений всех сетов на верхней границе повторов с целевым RIR — минимальный шаг; затем нижняя граница повторов.","Не переносить прибавку жима на гантели или блок. При боли прекратить провоцирующее упражнение."]},{"id":"h2-2-b4-seated_leg_curl","key":"seated_leg_curl","name":"Сгибание ног сидя","sets":"2","reps":"10–15","role":"optional_legs","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":3,"max":4},"optional":true,"condition":"Необязательная ОФП только при согласованной переносимости. Не в разгрузке и тейпере.","excludeFromTonnage":false,"restSeconds":90,"notes":["Не входит в основную матрицу; без боли и без одновременного увеличения других нагрузок."]}],"notes":["Стимул создают рабочие повторения с запасом, а не дополнительный список жимов. Первые подходы легче последних.","Сначала симптомы/седация, затем готовность, страховка и разминка. Никаких автоматических медицинских уровней по проценту.","RPE — фактическая оценка запаса, не прогноз из килограммов. Разминка строится от выбранного рабочего веса и не превышает личного предела.","При нехватке времени: основной жим с полноценным отдыхом → одна тяга → остальная подсобка → необязательная ОФП."],"branches":[]}'::jsonb, '[]'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET cycle_id=EXCLUDED.cycle_id, label=EXCLUDED.label, title=EXCLUDED.title, notes=EXCLUDED.notes, sort_order=EXCLUDED.sort_order, kind=EXCLUDED.kind, cardio_zone=EXCLUDED.cardio_zone, cardio_minutes=EXCLUDED.cardio_minutes, day_in_cycle=EXCLUDED.day_in_cycle, warmup_level=EXCLUDED.warmup_level, prescription=EXCLUDED.prescription, branches=EXCLUDED.branches;
