Одинаковое касание и пауза около секунды; без отказа и компенсации пропусков.', 240, 'v4:h2-2-b4-paused_bench_0', 'primary_bench', 65.21739130434783, 65.21739130434783, 75, 75, 6, 7.5, false, NULL, false, '{"id":"h2-2-b4-paused_bench_0","key":"paused_bench_0","name":"Жим лёжа с паузой","sets":"3","reps":"8","role":"primary_bench","percent":{"min":65.21739130434783,"max":65.21739130434783},"exampleKg":{"min":75,"max":75},"targetRpe":{"min":6,"max":7.5},"targetRir":null,"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":240,"notes":["Вес — стартовый пример при R=115, а не обязательное назначение. Фактический RPE важнее цифры.","До последнего сета при RPE около 7,5 снизить вес на 2,5–5 кг; при RPE 8 обычный основной жим закончить.","Одинаковое касание и пауза около секунды; без отказа и компенсации пропусков."],"afterControlLight":false,"progressionEligible":true}'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET workout_id=EXCLUDED.workout_id, sort_order=EXCLUDED.sort_order, name=EXCLUDED.name, weight_text=EXCLUDED.weight_text, pct_of_tm=EXCLUDED.pct_of_tm, target_reps=EXCLUDED.target_reps, target_sets=EXCLUDED.target_sets, target_rir_min=EXCLUDED.target_rir_min, target_rir_max=EXCLUDED.target_rir_max, comment=EXCLUDED.comment, rest_seconds=EXCLUDED.rest_seconds, role=EXCLUDED.role, pct_min=EXCLUDED.pct_min, pct_max=EXCLUDED.pct_max, example_kg_min=EXCLUDED.example_kg_min, example_kg_max=EXCLUDED.example_kg_max, target_rpe_min=EXCLUDED.target_rpe_min, target_rpe_max=EXCLUDED.target_rpe_max, is_optional=EXCLUDED.is_optional, condition_code=EXCLUDED.condition_code, exclude_from_tonnage=EXCLUDED.exclude_from_tonnage, prescription=EXCLUDED.prescription;
