INSERT INTO workouts (cycle_id, label, title, notes, sort_order, kind, cardio_zone, cardio_minutes, program_key, day_in_cycle, warmup_level, prescription, branches) VALUES ((SELECT id FROM cycles WHERE program_version='h2-v9-4.0' AND program_key='v4:h2-6'), 'B3', 'Лёгкое кардио и условная поддержка', 'Жёлтый: не более min(план,15 минут), легко. Оранжевый: отдых или короткая привычная прогулка, если безопасно. Красный: отмена. Нулевой план остаётся нулевым.
