-- h2-8 Закрепление гипертрофии
INSERT INTO cycles (number, name, macrocycle, notes, sort_order, block, program_version, program_key, day_offset, checkpoint, rules) VALUES (8, 'Закрепление гипертрофии', 2, 'Повтор продуктивной схемы — намеренное решение. Успешный вес не обязан меняться каждый цикл; важны качественные повторения.

Не догонять пропущенное. При необходимости смещать календарь без уплотнения жимовых дней.

Пересмотреть программу после 2–3 циклов по реальному журналу.', 8, 'h2', 'h2-v9-4.0', 'v4:h2-8', 56, NULL, '["Не догонять пропущенное. При необходимости смещать календарь без уплотнения жимовых дней.","Пересмотреть программу после 2–3 циклов по реальному журналу."]'::jsonb) ON CONFLICT (program_version, program_key) WHERE program_key IS NOT NULL DO UPDATE SET number=EXCLUDED.number, name=EXCLUDED.name, macrocycle=EXCLUDED.macrocycle, notes=EXCLUDED.notes, sort_order=EXCLUDED.sort_order, block=EXCLUDED.block, day_offset=EXCLUDED.day_offset, checkpoint=EXCLUDED.checkpoint, rules=EXCLUDED.rules;
INSERT INTO workouts (cycle_id, label, title, notes, sort_order, kind, cardio_zone, cardio_minutes, program_key, day_in_cycle, warmup_level, prescription, branches) VALUES ((SELECT id FROM cycles WHERE program_version='h2-v9-4.0' AND program_key='v4:h2-8'), 'B1', 'Лёгкое кардио и условная поддержка', 'Жёлтый: не более min(план,15 минут), легко. Оранжевый: отдых или короткая привычная прогулка, если безопасно. Красный: отмена. Нулевой план остаётся нулевым.
