INSERT INTO workouts (cycle_id, label, title, notes, sort_order, kind, cardio_zone, cardio_minutes, program_key, day_in_cycle, warmup_level, prescription, branches) VALUES ((SELECT id FROM cycles WHERE program_version='h2-v9-4.0' AND program_key='v4:v9-4'), 'B4', 'Зал B · Тяжёлые тройки', 'Если первый сет уже около RPE 7,5, следующие выполняются легче. Три подхода — верхний объём, а не обязанность любой ценой.
Сначала симптомы/седация, затем готовность, страховка и разминка. Никаких автоматических медицинских уровней по проценту.
RPE — фактическая оценка запаса, не прогноз из килограммов. Разминка строится от выбранного рабочего веса и не превышает личного предела.
При нехватке времени: основной жим с полноценным отдыхом → одна тяга → остальная подсобка → необязательная ОФП.', 4, 'strength', NULL, NULL, 'v4:v9-4-b4', 8, 'normal', '{"id":"v9-4-b4","slot":"B4","day":8,"kind":"strength","title":"Зал B · Тяжёлые тройки","duration":{"min":55,"max":75},"isRestDay":false,"isDeload":false,"isTaper":false,"isControl":false,"cardio":null,"warmupLevel":"normal","exercises":[{"id":"v9-4-b4-paused_bench_0","key":"paused_bench_0","name":"Жим лёжа с паузой","sets":"3","reps":"3","role":"primary_bench","percent":{"min":80.43478260869566,"max":80.43478260869566},"exampleKg":{"min":92.5,"max":92.5},"targetRpe":{"min":6,"max":7.5},"targetRir":null,"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":240,"notes":["Вес — стартовый пример при R=115, а не обязательное назначение. Фактический RPE важнее цифры.","До последнего сета при RPE около 7,5 снизить вес на 2,5–5 кг; при RPE 8 обычный основной жим закончить.","Одинаковое касание и пауза около секунды; без отказа и компенсации пропусков."],"afterControlLight":false,"progressionEligible":true},{"id":"v9-4-b4-incline_dumbbell_press","key":"incline_dumbbell_press","name":"Наклонный жим гантелей 15–30°","sets":"2","reps":"6–10","role":"chest_accessory","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":3,"max":3},"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":120,"notes":["Вес подбирать отдельно по запасу. После двух выполнений всех сетов на верхней границе повторов с целевым RIR — минимальный шаг; затем нижняя граница повторов.","Не переносить прибавку жима на гантели или блок. При боли прекратить провоцирующее упражнение."]},{"id":"v9-4-b4-lat_pulldown","key":"lat_pulldown","name":"Верхний блок","sets":"3","reps":"8–12","role":"back_accessory","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":3,"max":3},"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":120,"notes":["Вес подбирать отдельно 