INSERT INTO workouts (cycle_id, label, title, notes, sort_order, kind, cardio_zone, cardio_minutes, program_key, day_in_cycle, warmup_level, prescription, branches) VALUES ((SELECT id FROM cycles WHERE program_version='h2-v9-4.0' AND program_key='v4:v9-5'), 'B3', 'Лёгкое кардио и условная поддержка', 'Жёлтый: не более min(план,15 минут), легко. Оранжевый: отдых или короткая привычная прогулка, если безопасно. Красный: отмена. Нулевой план остаётся нулевым.
Поддержка опциональна, по переносимости. Нет автоматического перехода на следующую ступень раз в три цикла.', 3, 'cardio', 'Z1', '25 минут всего, очень легко, свободный разговор.', 'v4:v9-5-b3', 7, NULL, '{"id":"v9-5-b3","slot":"B3","day":7,"kind":"cardio","title":"Лёгкое кардио и условная поддержка","duration":{"min":25,"max":25},"isRestDay":false,"isDeload":true,"isTaper":false,"isControl":false,"cardio":{"zone":"Z1","warmupMinutes":0,"mainMinutes":{"min":25,"max":25},"cooldownMinutes":0,"modality":"comfortable_low_impact","prescriptionText":"25 минут всего, очень легко, свободный разговор."},"warmupLevel":null,"exercises":[{"id":"v9-5-b3-dead_bug","key":"dead_bug","name":"Dead bug","sets":"1","reps":"5 на сторону","role":"rehab","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":null,"optional":true,"condition":"Только при согласованной переносимости; выбранный режим заменяет, а не дополняет этот комплекс.","excludeFromTonnage":true,"restSeconds":45,"notes":["Уменьшить рычаг при потере контроля.","Один спокойный круг, обычно 6–10 минут. Автоматической прогрессии по календарю нет."]},{"id":"v9-5-b3-side_plank","key":"side_plank","name":"Боковая планка с колен","sets":"1","reps":"10–15 с на сторону","role":"rehab","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":null,"optional":true,"condition":"Только при согласованной переносимости; выбранный режим заменяет, а не дополняет этот комплекс.","excludeFromTonnage":true,"restSeconds":45,"notes":["Короткое удержание; не задерживать дыхание.","Один спокойный круг, обычно 6–10 минут. Автоматической прогрессии по календарю нет."]},{"id":"v9-5-b3-wall_slide","key":"wall_slide","name":"Скольжения рук по стене","sets":"1","reps":"8","role":"rehab","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":null,"optional":true,"condition":"Только при согласованной переносимости; выбранный режим заменяет, а не дополняет этот комплекс.","excludeFromTonnage":true,"restSeconds":45,"notes":["Комфортная амплитуда, без боли.","Один спокойный круг, обычно 6–10 минут. Автоматической прогрессии по календарю нет."]}],"notes":["Жёлтый: не более min(план,15 минут), легко. Оранжевый: отдых или короткая привычная прогулка, если безопасно. Красный: отмена. Нулевой план остаётся нулевым.","Поддержка опциональна, по переносимости. Нет автоматического перехода на следующую ступень раз в три цикла."],"branches":[]}'::jsonb, '[]'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET cycle_id=EXCLUDED.cycle_id, label=EXCLUDED.label, title=EXCLUDED.title, notes=EXCLUDED.notes, sort_order=EXCLUDED.sort_order, kind=EXCLUDED.kind, cardio_zone=EXCLUDED.cardio_zone, cardio_minutes=EXCLUDED.cardio_minutes, day_in_cycle=EXCLUDED.day_in_cycle, warmup_level=EXCLUDED.warmup_level, prescription=EXCLUDED.prescription, branches=EXCLUDED.branches;
