INSERT INTO workouts (cycle_id, label, title, notes, sort_order, kind, cardio_zone, cardio_minutes, program_key, day_in_cycle, warmup_level, prescription, branches) VALUES ((SELECT id FROM cycles WHERE program_version='h2-v9-4.0' AND program_key='v4:v9-6'), 'B2', 'Зал A · Интенсификация I', 'Вернуться к качественному рабочему объёму после разгрузки. Результат КТ обновляет расчётную базу только по правилам раздела 4.
Сначала симптомы/седация, затем готовность, страховка и разминка. Никаких автоматических медицинских уровней по проценту.
RPE — фактическая оценка запаса, не прогноз из килограммов. Разминка строится от выбранного рабочего веса и не превышает личного предела.
При нехватке времени: основной жим с полноценным отдыхом → одна тяга → остальная подсобка → необязательная ОФП.', 2, 'strength', NULL, NULL, 'v4:v9-6-b2', 4, 'normal', '{"id":"v9-6-b2","slot":"B2","day":4,"kind":"strength","title":"Зал A · Интенсификация I","duration":{"min":55,"max":75},"isRestDay":false,"isDeload":false,"isTaper":false,"isControl":false,"cardio":null,"warmupLevel":"normal","exercises":[{"id":"v9-6-b2-paused_bench_0","key":"paused_bench_0","name":"Жим лёжа с паузой","sets":"4","reps":"3","role":"primary_bench","percent":{"min":82.6086956521739,"max":82.6086956521739},"exampleKg":{"min":95,"max":95},"targetRpe":{"min":6,"max":8},"targetRir":null,"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":240,"notes":["Вес — стартовый пример при R=115, а не обязательное назначение. Фактический RPE важнее цифры.","До последнего сета при RPE около 7,5 снизить вес на 2,5–5 кг; при RPE 8 обычный основной жим закончить.","Одинаковое касание и пауза около секунды; без отказа и компенсации пропусков."],"afterControlLight":false,"progressionEligible":true},{"id":"v9-6-b2-chest_supported_row","key":"chest_supported_row","name":"Тяга с опорой грудью","sets":"3","reps":"6–10","role":"upper_back","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":3,"max":3},"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":120,"notes":["Вес подбирать отдельно по запасу. После двух выполнений всех сетов на верхней границе повторов с целевым RIR — минимальный шаг; затем нижняя граница повторов.","Не переносить прибавку жима на гантели или блок. При боли прекратить провоцирующее упражнение."]},{"id":"v9-6-b2-triceps_pushdown","key":"triceps_pushdown","name":"Разгибание рук на блоке","sets":"2","reps":"10–15","role":"triceps_accessory","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":3,"max":3},"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":90,"notes":["Вес подбирать отдельно по з