INSERT INTO workouts (cycle_id, label, title, notes, sort_order, kind, cardio_zone, cardio_minutes, program_key, day_in_cycle, warmup_level, prescription, branches) VALUES ((SELECT id FROM cycles WHERE program_version='h2-v9-4.0' AND program_key='v4:v9-7'), 'B2', 'Зал A · Интенсификация II', 'Больше практики двоек без увеличения числа упражнений. Последний сет не должен превращаться в одиночные дожимы.
Сначала симптомы/седация, затем готовность, страховка и разминка. Никаких автоматических медицинских уровней по проценту.
RPE — фактическая оценка запаса, не прогноз из килограммов. Разминка строится от выбранного рабочего веса и не превышает личного предела.
При нехватке времени: основной жим с полноценным отдыхом → одна тяга → остальная подсобка → необязательная ОФП.', 2, 'strength', NULL, NULL, 'v4:v9-7-b2', 4, 'normal', '{"id":"v9-7-b2","slot":"B2","day":4,"kind":"strength","title":"Зал A · Интенсификация II","duration":{"min":55,"max":75},"isRestDay":false,"isDeload":false,"isTaper":false,"isControl":false,"cardio":null,"warmupLevel":"normal","exercises":[{"id":"v9-7-b2-paused_bench_0","key":"paused_bench_0","name":"Жим лёжа с паузой","sets":"4","reps":"2","role":"primary_bench","percent":{"min":84.78260869565217,"max":84.78260869565217},"exampleKg":{"min":97.5,"max":97.5},"targetRpe":{"min":6,"max":8},"targetRir":null,"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":240,"notes":["Вес — стартовый пример при R=115, а не обязательное назначение. Фактический RPE важнее цифры.","До последнего сета при RPE около 7,5 снизить вес на 2,5–5 кг; при RPE 8 обычный основной жим закончить.","Одинаковое касание и пауза около секунды; без отказа и компенсации пропусков."],"afterControlLight":false,"progressionEligible":true},{"id":"v9-7-b2-chest_supported_row","key":"chest_supported_row","name":"Тяга с опорой грудью","sets":"3","reps":"6–10","role":"upper_back","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":3,"max":3},"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":120,"notes":["Вес подбирать отдельно по запасу. После двух выполнений всех сетов на верхней границе повторов с целевым RIR — минимальный шаг; затем нижняя граница повторов.","Не переносить прибавку жима на гантели или блок. При боли прекратить провоцирующее упражнение."]},{"id":"v9-7-b2-triceps_pushdown","key":"triceps_pushdown","name":"Разгибание рук на блоке","sets":"2","reps":"10–15","role":"triceps_accessory","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":3,"max":3},"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":90,"notes":["Вес подбирать отдельно по запасу. После двух выполнений всех сетов на верхней границе повторов с целевым RIR — минимальный шаг; затем нижняя граница повторов.","Не переносить прибавку жима на гантели или блок. При боли прекратить провоцирующее упражнение."]},{"id":"v9-7-b2-leg_extension","key":"leg_extension","name":"Разгибание ног","sets":"2","reps":"10–15","role":"optional_legs","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":3,"max":4},"optional":true,"condition":"Необязательная ОФП только при согласованной переносимости. Не в разгрузке и тейпере.","excludeFromTonnage":false,"restSeconds":90,"notes":["Не входит в основную матрицу; без боли и без одновременного увеличения других нагрузок."]}],"notes":["Больше практики двоек без увеличения числа упражнений. Последний сет не должен превращаться в одиночные дожимы.","Сначала симптомы/седация, затем готовность, страховка и разминка. Никаких автоматических медицинских уровней по проценту.","RPE — фактическая оценка запаса, не прогноз из килограммов. Разминка строится от выбранного рабочего веса и не превышает личного предела.","При нехватке времени: основной жим с полноценным отдыхом → одна тяга → остальная подсобка → необязательная ОФП."],"branches":[]}'::jsonb, '[]'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET cycle_id=EXCLUDED.cycle_id, label=EXCLUDED.label, title=EXCLUDED.title, notes=EXCLUDED.notes, sort_order=EXCLUDED.sort_order, kind=EXCLUDED.kind, cardio_zone=EXCLUDED.cardio_zone, cardio_minutes=EXCLUDED.cardio_minutes, day_in_cycle=EXCLUDED.day_in_cycle, warmup_level=EXCLUDED.warmup_level, prescription=EXCLUDED.prescription, branches=EXCLUDED.branches;
INSERT INTO workout_exercises (workout_id, sort_order, name, weight_text, pct_of_tm, target_reps, target_sets, target_rir_min, target_rir_max, comment, rest_seconds, program_key, role, pct_min, pct_max, example_kg_min, example_kg_max, target_rpe_min, target_rpe_max, is_optional, condition_code, exclude_from_tonnage, prescription) VALUES ((SELECT id FROM workouts WHERE program_key='v4:v9-7-b2'), 1, 'Жим лёжа с паузой', '97.5 кг · стартовый пример при R=115', 84.78260869565217, '2', '4', NULL, NULL, 'Вес — стартовый пример при R=115, а не обязательное назначение. Фактический RPE важнее цифры.
