INSERT INTO workouts (cycle_id, label, title, notes, sort_order, kind, cardio_zone, cardio_minutes, program_key, day_in_cycle, warmup_level, prescription, branches) VALUES ((SELECT id FROM cycles WHERE program_version='h2-v9-4.0' AND program_key='v4:v9-8'), 'B2', 'Зал A · Специфическая сила I', 'Основная ветка — двойки, без обязательных синглов. При индивидуальном потолке 85% от R=115 максимум — 97,5 кг, не 100.
Сначала симптомы/седация, затем готовность, страховка и разминка. Никаких автоматических медицинских уровней по проценту.
RPE — фактическая оценка запаса, не прогноз из килограммов. Разминка строится от выбранного рабочего веса и не превышает личного предела.
При нехватке времени: основной жим с полноценным отдыхом → одна тяга → остальная подсобка → необязательная ОФП.', 2, 'strength', NULL, NULL, 'v4:v9-8-b2', 4, 'normal', '{"id":"v9-8-b2","slot":"B2","day":4,"kind":"strength","title":"Зал A · Специфическая сила I","duration":{"min":55,"max":75},"isRestDay":false,"isDeload":false,"isTaper":false,"isControl":false,"cardio":null,"warmupLevel":"normal","exercises":[{"id":"v9-8-b2-paused_bench_0","key":"paused_bench_0","name":"Жим лёжа с паузой","sets":"3","reps":"2","role":"primary_bench","percent":{"min":86.95652173913044,"max":86.95652173913044},"exampleKg":{"min":100,"max":100},"targetRpe":{"min":6,"max":8},"targetRir":null,"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":240,"notes":["Вес — стартовый пример при R=115, а не обязательное назначение. Фактический RPE важнее цифры.","До последнего сета при RPE около 7,5 снизить вес на 2,5–5 кг; при RPE 8 обычный основной жим закончить.","Одинаковое касание и пауза около секунды; без отказа и компенсации пропусков."],"afterControlLight":false,"progressionEligible":true},{"id":"v9-8-b2-chest_supported_row","key":"chest_supported_row","name":"Тяга с опорой грудью","sets":"3","reps":"6–10","role":"upper_back","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":3,"max":3},"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":120,"notes":["Вес подбирать отдельно по запасу. После двух выполнений всех сетов на верхней границе повторов с целевым RIR — минимальный шаг; затем нижняя граница повторов.","Не переносить прибавку жима на гантели или блок. При боли прекратить провоцирующее упражнение."]},{"id":"v9-8-b2-triceps_pushdown","key":"triceps_pushdown","name":"Разгибание рук на блоке","sets":"2","reps":"10–15","role":"triceps_accessory","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":3,"max":3},"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":90,"notes":["Вес подбирать отдельно по запасу. После двух выполнений всех сетов на верхней границе повторов с целевым RIR — минимальный шаг; затем нижняя граница повторов.","Не переносить прибавку жима на гантели или блок. При боли прекратить провоцирующее упражнение."]},{"id":"v9-8-b2-leg_extension","key":"leg_extension","name":"Разгибание ног","sets":"2","reps":"10–15","role":"optional_legs","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":3,"max":4},"optional":true,"condition":"Необязательная ОФП только при согласованной переносимости. Не в разгрузке и тейпере.","excludeFromTonnage":false,"restSeconds":90,"notes":["Не входит в основную матрицу; без боли и без одновременного увеличения других нагрузок."]}],"notes":["Основная ветка — двойки, без обязательных синглов. При индивидуальном потолке 85% от R=115 максимум — 97,5 кг, не 100.","Сначала симптомы/седация, затем готовность, страховка и разминка. Никаких автоматических медицинских уровней по проценту.","RPE — фактическая оценка запаса, не прогноз из килограммов. Разминка строится от выбранного рабочего веса и не превышает личного предела.","При нехватке времени: основной жим с полноценным отдыхом → одна тяга → остальная подсобка → необязательная ОФП."],"branches":[{"id":"triple","default":true,"name":"Основная ветка · контрольная тройка","exercises":[]},{"id":"direct_1rm","default":false,"name":"Отдельная подготовка к 1ПМ","conditions":["Отдельно согласованные усилие и натуживание, опыт, страховка и понятная спортивная цель.","Решение до цикла 17; подтверждение или отмена на КТ4. Замена, не добавление к основной строке.","Нет синглов в Ц17/19 или были проблемы — не пробовать первый максимум в день 172."],"exercises":[{"id":"v9-8-b2-direct_0","key":"direct_0","name":"Жим с паузой · отдельная ветка 1ПМ","sets":"1","reps":"1","role":"conditional_single","percent":{"min":89.13043478260869,"max":89.13043478260869},"exampleKg":{"min":102.5,"max":102.5},"targetRpe":{"min":6,"max":7},"targetRir":null,"optional":true,"condition":null,"excludeFromTonnage":false,"restSeconds":300,"notes":["Только вместо основной жимовой строки; общий индивидуальный предел сохраняется.","Вес — пример при R=115; усилие и ограничения имеют приоритет."],"branchId":"direct_1rm"},{"id":"v9-8-b2-direct_1","key":"direct_1","name":"Жим с паузой · отдельная ветка 1ПМ","sets":"2","reps":"2","role":"primary_backoff","percent":{"min":84.78260869565217,"max":84.78260869565217},"exampleKg":{"min":97.5,"max":97.5},"targetRpe":{"min":6,"max":7},"targetRir":null,"optional":true,"condition":null,"excludeFromTonnage":false,"restSeconds":300,"notes":["Только вместо основной жимовой строки; общий индивидуальный предел сохраняется.","Вес — пример при R=115; усилие и ограничения имеют приоритет."],"branchId":"direct_1rm"}]}]}'::jsonb, '[{"id":"triple","default":true,"name":"Основная ветка · контрольная тройка","exercises":[]},{"id":"direct_1rm","default":false,"name":"Отдельная подготовка к 1ПМ","conditions":["Отдельно согласованные усилие и натуживание, опыт, страховка и понятная спортивная цель.","Решение до цикла 17; подтверждение или отмена на КТ4. Замена, не добавление к основной строке.","Нет синглов в Ц17/19 или были проблемы — не пробовать первый максимум в день 172."],"exercises":[{"id":"v9-8-b2-direct_0","key":"direct_0","name":"Жим с паузой · отдельная ветка 1ПМ","sets":"1","reps":"1","role":"conditional_single","percent":{"min":89.13043478260869,"max":89.13043478260869},"exampleKg":{"min":102.5,"max":102.5},"targetRpe":{"min":6,"max":7},"targetRir":null,"optional":true,"condition":null,"excludeFromTonnage":false,"restSeconds":300,"notes":["Только вместо основной жимовой строки; общий индивидуальный предел сохраняется.","Вес — пример при R=115; усилие и ограничения имеют приоритет."],"branchId":"direct_1rm"},{"id":"v9-8-b2-direct_1","key":"direct_1","name":"Жим с паузой · отдельная ветка 1ПМ","sets":"2","reps":"2","role":"primary_backoff","percent":{"min":84.78260869565217,"max":84.78260869565217},"exampleKg":{"min":97.5,"max":97.5},"targetRpe":{"min":6,"max":7},"targetRir":null,"optional":true,"condition":null,"excludeFromTonnage":false,"restSeconds":300,"notes":["Только вместо основной жимовой строки; общий индивидуальный предел сохраняется.","Вес — пример при R=115; усилие и ограничения имеют приоритет."],"branchId":"direct_1rm"}]}]'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET cycle_id=EXCLUDED.cycle_id, label=EXCLUDED.label, title=EXCLUDED.title, notes=EXCLUDED.notes, sort_order=EXCLUDED.sort_order, kind=EXCLUDED.kind, cardio_zone=EXCLUDED.cardio_zone, cardio_minutes=EXCLUDED.cardio_minutes, day_in_cycle=EXCLUDED.day_in_cycle, warmup_level=EXCLUDED.warmup_level, prescription=EXCLUDED.prescription, branches=EXCLUDED.branches;
INSERT INTO workout_exercises (workout_id, sort_order, name, weight_text, pct_of_tm, target_reps, target_sets, target_rir_min, target_rir_max, comment, rest_seconds, program_key, role, pct_min, pct_max, example_kg_min, example_kg_max, target_rpe_min, target_rpe_max, is_optional, condition_code, exclude_from_tonnage, prescription) VALUES ((SELECT id FROM workouts WHERE program_key='v4:v9-8-b2'), 1, 'Жим лёжа с паузой', '100 кг · стартовый пример при R=115', 86.95652173913044, '2', '3', NULL, NULL, 'Вес — стартовый пример при R=115, а не обязательное назначение. Фактический RPE важнее цифры.
