нка строится от выбранного рабочего веса и не превышает личного предела.","При нехватке времени: основной жим с полноценным отдыхом → одна тяга → остальная подсобка → необязательная ОФП."],"branches":[]}'::jsonb, '[]'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET cycle_id=EXCLUDED.cycle_id, label=EXCLUDED.label, title=EXCLUDED.title, notes=EXCLUDED.notes, sort_order=EXCLUDED.sort_order, kind=EXCLUDED.kind, cardio_zone=EXCLUDED.cardio_zone, cardio_minutes=EXCLUDED.cardio_minutes, day_in_cycle=EXCLUDED.day_in_cycle, warmup_level=EXCLUDED.warmup_level, prescription=EXCLUDED.prescription, branches=EXCLUDED.branches;
