INSERT INTO workout_exercises (workout_id, sort_order, name, weight_text, pct_of_tm, target_reps, target_sets, target_rir_min, target_rir_max, comment, rest_seconds, program_key, role, pct_min, pct_max, example_kg_min, example_kg_max, target_rpe_min, target_rpe_max, is_optional, condition_code, exclude_from_tonnage, prescription) VALUES ((SELECT id FROM workouts WHERE program_key='v4:v9-9-b4'), 2, 'Верхний блок', '4–5 RIR', NULL, '8–10', '2', 4, 5, 'Вес подбирать отдельно по запасу. После двух выполнений всех сетов на верхней границе повторов с целевым RIR — минимальный шаг; затем нижняя граница повторов.
Не переносить прибавку жима на гантели или блок. При боли прекратить провоцирующее упражнение.', 90, 'v4:v9-9-b4-lat_pulldown', 'back_accessory', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, false, '{"id":"v9-9-b4-lat_pulldown","key":"lat_pulldown","name":"Верхний блок","sets":"2","reps":"8–10","role":"back_accessory","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":4,"max":5},"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":90,"notes":["Вес подбирать отдельно по запасу. После двух выполнений всех сетов на верхней границе повторов с целевым RIR — минимальный шаг; затем нижняя граница повторов.","Не переносить прибавку жима на гантели или блок. При боли прекратить провоцирующее упражнение."]}'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET workout_id=EXCLUDED.workout_id, sort_order=EXCLUDED.sort_order, name=EXCLUDED.name, weight_text=EXCLUDED.weight_text, pct_of_tm=EXCLUDED.pct_of_tm, target_reps=EXCLUDED.target_reps, target_sets=EXCLUDED.target_sets, target_rir_min=EXCLUDED.target_rir_min, target_rir_max=EXCLUDED.target_rir_max, comment=EXCLUDED.comment, rest_seconds=EXCLUDED.rest_seconds, role=EXCLUDED.role, pct_min=EXCLUDED.pct_min, pct_max=EXCLUDED.pct_max, example_kg_min=EXCLUDED.example_kg_min, example_kg_max=EXCLUDED.example_kg_max, target_rpe_min=EXCLUDED.target_rpe_min, target_rpe_max=EXCLUDED.target_rpe_max, is_optional=EXCLUDED.is_optional, condition_code=EXCLUDED.condition_code, exclude_from_tonnage=EXCLUDED.exclude_from_tonnage, prescription=EXCLUDED.prescription;

-- v9-10 Специфическая сила II
INSERT INTO cycles (number, name, macrocycle, notes, sort_order, block, program_version, program_key, day_offset, checkpoint, rules) VALUES (10, 'Специфическая сила II', 4, 'Последний полноценный силовой цикл. Лёгкая тройка после двоек учитывает уже накопленную усталость; её можно убрать.

Не догонять пропущенное. При необходимости смещать календарь без уплотнения жимовых дней.

Пересмотреть программу после 2–3 циклов по реальному журналу.', 19, 'v9', 'h2-v9-4.0', 'v4:v9-10', 144, NULL, '["Не догонять пропущенное. При необходимости смещать календарь без уплотнения жимовых дней.","Пересмотреть программу после 2–3 циклов по реальному журналу."]'::jsonb) ON CONFLICT (program_version, program_key) WHERE program_key IS NOT NULL DO UPDATE SET number=EXCLUDED.number, name=EXCLUDED.name, macrocycle=EXCLUDED.macrocycle, notes=EXCLUDED.notes, sort_order=EXCLUDED.sort_order, block=EXCLUDED.block, day_offset=EXCLUDED.day_offset, checkpoint=EXCLUDED.checkpoint, rules=EXCLUDED.rules;
INSERT INTO workouts (cycle_id, label, title, notes, sort_order, kind, cardio_zone, cardio_minutes, program_key, day_in_cycle, warmup_level, prescription, branches) VALUES ((SELECT id FROM cycles WHERE program_version='h2-v9-4.0' AND program_key='v4:v9-10'), 'B1', 'Лёгкое кардио и условная поддержка', 'Жёлтый: не более min(план,15 минут), легко. Оранжевый: отдых или короткая привычная прогулка, если безопасно. Красный: отмена. Нулевой план остаётся нулевым.
Поддержка опциональна, по переносимости. Нет автоматического перехода на следующую ступень раз в три цикла.', 1, 'cardio', 'Z1', '15 минут всего, очень легко, свободный разговор.', 'v4:v9-10-b1', 3, NULL, '{"id":"v9-10-b1","slot":"B1","day":3,"kind":"cardio","title":"Лёгкое кардио и условная поддержка","duration":{"min":15,"max":15},"isRestDay":false,"isDeload":false,"isTaper":false,"isControl":false,"cardio":{"zone":"Z1","warmupMinutes":0,"mainMinutes":{"min":15,"max":15},"cooldownMinutes":0,"modality":"comfortable_low_impact","prescriptionText":"15 минут всего, очень легко, свободный разговор."},"warmupLevel":null,"exercises":[{"id":"v9-10-b1-bird_dog","key":"bird_dog","name":"Bird-dog","sets":"1","reps":"5 на сторону","role":"rehab","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":null,"optional":true,"condition":"Только при согласованной переносимости; выбранный режим заменяет, а не дополняет этот комплекс.","excludeFromTonnage":true,"restSeconds":45,"notes":["Удержание 2–3 с; без запрокидывания поясницы.","Один спокойный круг, обычно 6–10 минут. Автоматической прогрессии по календарю нет."]},{"id":"v9-10-b1-glute_bridge","key":"glute_bridge","name":"Ягодичный мост","sets":"1","reps":"8","role":"rehab","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":null,"optional":true,"condition":"Только при согласованной переносимости; выбранный режим заменяет, а не дополняет этот комплекс.","excludeFromTonnage":true,"restSeconds":45,"notes":["Пауза 1 с; комфортная амплитуда.","Один спокойный круг, обычно 6–10 минут. Автоматической прогрессии по календарю нет."]},{"id":"v9-10-b1-external_rotation","key":"external_rotation","name":"Внешняя ротация","sets":"1","reps":"12 на сторону","role":"rehab","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":null,"optional":true,"condition":"Только при согласованной переносимости; выбранный режим заменяет, а не дополняет этот комплекс.","excludeFromTonnage":true,"restSeconds":45,"notes":["Очень лёгкое сопротивление, без боли.","Один спокойный круг, обычно 6–10 минут. Автоматической прогрессии по календарю нет."]}],"notes":["Жёлтый: не более min(план,15 минут), легко. Оранжевый: отдых или короткая привычная прогулка, если безопасно. Красный: отмена. Нулевой план остаётся нулевым.","Поддержка опциональна, по переносимости. Нет автоматического перехода на следующую ступень раз в три цикла."],"branches":[]}'::jsonb, '[]'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET cycle_id=EXCLUDED.cycle_id, label=EXCLUDED.label, title=EXCLUDED.title, notes=EXCLUDED.notes, sort_order=EXCLUDED.sort_order, kind=EXCLUDED.kind, cardio_zone=EXCLUDED.cardio_zone, cardio_minutes=EXCLUDED.cardio_minutes, day_in_cycle=EXCLUDED.day_in_cycle, warmup_level=EXCLUDED.warmup_level, prescription=EXCLUDED.prescription, branches=EXCLUDED.branches;
