INSERT INTO workouts (cycle_id, label, title, notes, sort_order, kind, cardio_zone, cardio_minutes, program_key, day_in_cycle, warmup_level, prescription, branches) VALUES ((SELECT id FROM cycles WHERE program_version='h2-v9-4.0' AND program_key='v4:v9-11'), 'B2', 'Зал A · Тейпер I и КТ4', 'За 16 дней до итога зафиксировать протокол. Если тройка неуместна по восстановлению, КТ пропускается, а подводка не удлиняется силовыми добавками.
Сначала симптомы/седация, затем готовность, страховка и разминка. Никаких автоматических медицинских уровней по проценту.
Контроль: одна тройка. При утомлении КТ пропускается без компенсации. После штатной 3@8 — только напечатанные лёгкие сеты; после итогового теста подсобки нет.
При нехватке времени: основной жим с полноценным отдыхом → одна тяга → остальная подсобка → необязательная ОФП.', 2, 'strength', NULL, NULL, 'v4:v9-11-b2', 4, 'control', '{"id":"v9-11-b2","slot":"B2","day":4,"kind":"strength","title":"Зал A · Тейпер I и КТ4","duration":{"min":40,"max":60},"isRestDay":false,"isDeload":false,"isTaper":true,"isControl":true,"cardio":null,"warmupLevel":"control","exercises":[{"id":"v9-11-b2-control_triple","key":"control_triple","name":"Контрольная тройка · жим с паузой","sets":"1","reps":"3","role":"calibration","percent":null,"exampleKg":null,"targetRpe":{"min":8,"max":8},"targetRir":null,"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":300,"notes":["Одна тройка; фактический RPE записывается без подгонки к восьми. Не повторять ради попадания в число.","Без недавней подтверждённой базы — знакомый консервативный вес на 3 повтора при RPE 6–7; не автоматические 100 кг.","Если ограничение не позволяет 3@8 — согласованный фиксированный вес, без пересчёта в максимум."],"afterControlLight":false,"progressionEligible":false},{"id":"v9-11-b2-paused_bench_1","key":"paused_bench_1","name":"Жим лёжа с паузой","sets":"1","reps":"2","role":"primary_backoff","percent":{"min":80.43478260869566,"max":80.43478260869566},"exampleKg":{"min":92.5,"max":92.5},"targetRpe":{"min":null,"max":6},"targetRir":null,"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":180,"notes":["Вес — стартовый пример при R=115, а не обязательное назначение. Фактический RPE важнее цифры.","После штатной КТ разрешены только эти лёгкие сеты ≤6. При симптомах, гриндере или нештатно тяжёлой тройке убрать.","Одинаковое касание и пауза около секунды; без отказа и компенсации пропусков."],"afterControlLight":true,"progressionEligible":false},{"id":"v9-11-b2-chest_supported_row","key":"chest_supported_row","name":"Тяга с опорой грудью","sets":"2","reps":"8–10","role":"upper_back","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":4,"max":5},"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":90,"notes":["Вес подбирать отдельно по запасу. После двух выполнений всех сетов на верхней границе повторов с целевым RIR — минимальный шаг; затем нижняя граница повторов.","Не переносить прибавку жима на гантели или блок. При боли прекратить провоцирующее упражнение."]}],"notes":["За 16 дней до итога зафиксировать протокол. Если тройка неуместна по восстановлению, КТ пропускается, а подводка не удлиняется силовыми добавками.","Сначала симптомы/седация, затем готовность, страховка и разминка. Никаких автоматических медицинских уровней по проценту.","Контроль: одна тройка. При утомлении КТ пропускается без компенсации. После штатной 3@8 — только напечатанные лёгкие сеты; после итогового теста подсобки нет.","При нехватке времени: основной жим с полноценным отдыхом → одна тяга → остальная подсобка → необязательная ОФП."],"branches":[]}'::jsonb, '[]'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET cycle_id=EXCLUDED.cycle_id, label=EXCLUDED.label, title=EXCLUDED.title, notes=EXCLUDED.notes, sort_order=EXCLUDED.sort_order, kind=EXCLUDED.kind, cardio_zone=EXCLUDED.cardio_zone, cardio_minutes=EXCLUDED.cardio_minutes, day_in_cycle=EXCLUDED.day_in_cycle, warmup_level=EXCLUDED.warmup_level, prescription=EXCLUDED.prescription, branches=EXCLUDED.branches;
INSERT INTO workout_exercises (workout_id, sort_order, name, weight_text, pct_of_tm, target_reps, target_sets, target_rir_min, target_rir_max, comment, rest_seconds, program_key, role, pct_min, pct_max, example_kg_min, example_kg_max, target_rpe_min, target_rpe_max, is_optional, condition_code, exclude_from_tonnage, prescription) VALUES ((SELECT id FROM workouts WHERE program_key='v4:v9-11-b2'), 1, 'Контрольная тройка · жим с паузой', '8 RPE', NULL, '3', '1', NULL, NULL, 'Одна тройка; фактический RPE записывается без подгонки к восьми. Не повторять ради попадания в число.
Без недавней подтверждённой базы — знакомый консервативный вес на 3 повтора при RPE 6–7; не автоматические 100 кг.
Если ограничение не позволяет 3@8 — согласованный фиксированный вес, без пересчёта в максимум.', 300, 'v4:v9-11-b2-control_triple', 'calibration', NULL, NULL, NULL, NULL, 8, 8, false, NULL, false, '{"id":"v9-11-b2-control_triple","key":"control_triple","name":"Контрольная тройка · жим с паузой","sets":"1","reps":"3","role":"calibration","percent":null,"exampleKg":null,"targetRpe":{"min":8,"max":8},"targetRir":null,"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":300,"notes":["Одна тройка; фактический RPE записывается без подгонки к восьми. Не повторять ради попадания в число.","Без недавней подтверждённой базы — знакомый консервативный вес на 3 повтора при RPE 6–7; не автоматические 100 кг.","Если ограничение не позволяет 3@8 — согласованный фиксированный вес, без пересчёта в максимум."],"afterControlLight":false,"progressionEligible":false}'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET workout_id=EXCLUDED.workout_id, sort_order=EXCLUDED.sort_order, name=EXCLUDED.name, weight_text=EXCLUDED.weight_text, pct_of_tm=EXCLUDED.pct_of_tm, target_reps=EXCLUDED.target_reps, target_sets=EXCLUDED.target_sets, target_rir_min=EXCLUDED.target_rir_min, target_rir_max=EXCLUDED.target_rir_max, comment=EXCLUDED.comment, rest_seconds=EXCLUDED.rest_seconds, role=EXCLUDED.role, pct_min=EXCLUDED.pct_min, pct_max=EXCLUDED.pct_max, example_kg_min=EXCLUDED.example_kg_min, example_kg_max=EXCLUDED.example_kg_max, target_rpe_min=EXCLUDED.target_rpe_min, target_rpe_max=EXCLUDED.target_rpe_max, is_optional=EXCLUDED.is_optional, condition_code=EXCLUDED.condition_code, exclude_from_tonnage=EXCLUDED.exclude_from_tonnage, prescription=EXCLUDED.prescription;
INSERT INTO workout_exercises (workout_id, sort_order, name, weight_text, pct_of_tm, target_reps, target_sets, target_rir_min, target_rir_max, comment, rest_seconds, program_key, role, pct_min, pct_max, example_kg_min, example_kg_max, target_rpe_min, target_rpe_max, is_optional, condition_code, exclude_from_tonnage, prescription) VALUES ((SELECT id FROM workouts WHERE program_key='v4:v9-11-b2'), 2, 'Жим лёжа с паузой', '92.5 кг · стартовый пример при R=115', 80.43478260869566, '2', '1', NULL, NULL, 'Вес — стартовый пример при R=115, а не обязательное назначение. Фактический RPE важнее цифры.
После штатной КТ разрешены только эти лёгкие сеты ≤6. При симптомах, гриндере или нештатно тяжёлой тройке убрать.
Одинаковое касание и пауза около секунды; без отказа и компенсации пропусков.', 180, 'v4:v9-11-b2-paused_bench_1', 'primary_backoff', 80.43478260869566, 80.43478260869566, 92.5, 92.5, NULL, 6, false, NULL, false, '{"id":"v9-11-b2-paused_bench_1","key":"paused_bench_1","name":"Жим лёжа с паузой","sets":"1","reps":"2","role":"primary_backoff","percent":{"min":80.43478260869566,"max":80.43478260869566},"exampleKg":{"min":92.5,"max":92.5},"targetRpe":{"min":null,"max":6},"targetRir":null,"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":180,"notes":["Вес — стартовый пример при R=115, а не обязательное назначение. Фактический RPE важнее цифры.","После штатной КТ разрешены только эти лёгкие сеты ≤6. При симптомах, гриндере или нештатно тяжёлой тройке убрать.","Одинаковое касание и пауза около секунды; без отказа и компенсации пропусков."],"afterControlLight":true,"progressionEligible":false}'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET workout_id=EXCLUDED.workout_id, sort_order=EXCLUDED.sort_order, name=EXCLUDED.name, weight_text=EXCLUDED.weight_text, pct_of_tm=EXCLUDED.pct_of_tm, target_reps=EXCLUDED.target_reps, target_sets=EXCLUDED.target_sets, target_rir_min=EXCLUDED.target_rir_min, target_rir_max=EXCLUDED.target_rir_max, comment=EXCLUDED.comment, rest_seconds=EXCLUDED.rest_seconds, role=EXCLUDED.role, pct_min=EXCLUDED.pct_min, pct_max=EXCLUDED.pct_max, example_kg_min=EXCLUDED.example_kg_min, example_kg_max=EXCLUDED.example_kg_max, target_rpe_min=EXCLUDED.target_rpe_min, target_rpe_max=EXCLUDED.target_rpe_max, is_optional=EXCLUDED.is_optional, condition_code=EXCLUDED.condition_code, exclude_from_tonnage=EXCLUDED.exclude_from_tonnage, prescription=EXCLUDED.prescription;
INSERT INTO workout_exercises (workout_id, sort_order, name, weight_text, pct_of_tm, target_reps, target_sets, target_rir_min, target_rir_max, comment, rest_seconds, program_key, role, pct_min, pct_max, example_kg_min, example_kg_max, target_rpe_min, target_rpe_max, is_optional, condition_code, exclude_from_tonnage, prescription) VALUES ((SELECT id FROM workouts WHERE program_key='v4:v9-11-b2'), 3, 'Тяга с опорой грудью', '4–5 RIR', NULL, '8–10', '2', 4, 5, 'Вес подбирать отдельно по запасу. После двух выполнений всех сетов на верхней границе повторов с целевым RIR — минимальный шаг; затем нижняя граница повторов.
Не переносить прибавку жима на гантели или блок. При боли прекратить провоцирующее упражнение.', 90, 'v4:v9-11-b2-chest_supported_row', 'upper_back', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, false, '{"id":"v9-11-b2-chest_supported_row","key":"chest_supported_row","name":"Тяга с опорой грудью","sets":"2","reps":"8–10","role":"upper_back","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":4,"max":5},"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":90,"notes":["Вес подбирать отдельно по запасу. После двух выполнений всех сетов на верхней границе повторов с целевым RIR — минимальный шаг; затем нижняя граница повторов.","Не переносить прибавку жима на гантели или блок. При боли прекратить провоцирующее упражнение."]}'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET workout_id=EXCLUDED.workout_id, sort_order=EXCLUDED.sort_order, name=EXCLUDED.name, weight_text=EXCLUDED.weight_text, pct_of_tm=EXCLUDED.pct_of_tm, target_reps=EXCLUDED.target_reps, target_sets=EXCLUDED.target_sets, target_rir_min=EXCLUDED.target_rir_min, target_rir_max=EXCLUDED.target_rir_max, comment=EXCLUDED.comment, rest_seconds=EXCLUDED.rest_seconds, role=EXCLUDED.role, pct_min=EXCLUDED.pct_min, pct_max=EXCLUDED.pct_max, example_kg_min=EXCLUDED.example_kg_min, example_kg_max=EXCLUDED.example_kg_max, target_rpe_min=EXCLUDED.target_rpe_min, target_rpe_max=EXCLUDED.target_rpe_max, is_optional=EXCLUDED.is_optional, condition_code=EXCLUDED.condition_code, exclude_from_tonnage=EXCLUDED.exclude_from_tonnage, prescription=EXCLUDED.prescription;
INSERT INTO workouts (cycle_id, label, title, notes, sort_order, kind, cardio_zone, cardio_minutes, program_key, day_in_cycle, warmup_level, prescription, branches) VALUES ((SELECT id FROM cycles WHERE program_version='h2-v9-4.0' AND program_key='v4:v9-11'), 'B3', 'Лёгкое кардио и условная поддержка', 'Жёлтый: не более min(план,15 минут), легко. Оранжевый: отдых или короткая привычная прогулка, если безопасно. Красный: отмена. Нулевой план остаётся нулевым.
Поддержка опциональна, по переносимости. Нет автоматического перехода на следующую ступень раз в три цикла.', 3, 'cardio', 'Z1', '25 минут всего, очень легко, свободный разговор.', 'v4:v9-11-b3', 7, NULL, '{"id":"v9-11-b3","slot":"B3","day":7,"kind":"cardio","title":"Лёгкое кардио и условная поддержка","duration":{"min":25,"max":25},"isRestDay":false,"isDeload":false,"isTaper":true,"isControl":false,"cardio":{"zone":"Z1","warmupMinutes":0,"mainMinutes":{"min":25,"max":25},"cooldownMinutes":0,"modality":"comfortable_low_impact","prescriptionText":"25 минут всего, очень легко, свободный разговор."},"warmupLevel":null,"exercises":[{"id":"v9-11-b3-dead_bug","key":"dead_bug","name":"Dead bug","sets":"1","reps":"5 на сторону","role":"rehab","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":null,"optional":true,"condition":"Только при согласованной переносимости; выбранный режим заменяет, а не дополняет этот комплекс.","excludeFromTonnage":true,"restSeconds":45,"notes":["Уменьшить рычаг при потере контроля.","Один спокойный круг, обычно 6–10 минут. Автоматической прогрессии по календарю нет."]},{"id":"v9-11-b3-side_plank","key":"side_plank","name":"Боковая планка с колен","sets":"1","reps":"10–15 с на сторону","role":"rehab","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":null,"optional":true,"condition":"Только при согласованной переносимости; выбранный режим заменяет, а не дополняет этот комплекс.","excludeFromTonnage":true,"restSeconds":45,"notes":["Короткое удержание; не задерживать дыхание.","Один спокойный круг, обычно 6–10 минут. Автоматической прогрессии по календарю нет."]},{"id":"v9-11-b3-wall_slide","key":"wall_slide","name":"Скольжения рук по стене","sets":"1","reps":"8","role":"rehab","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":null,"optional":true,"condition":"Только при согласованной переносимости; выбранный режим заменяет, а не дополняет этот комплекс.","excludeFromTonnage":true,"restSeconds":45,"notes":["Комфортная амплитуда, без боли.","Один спокойный круг, обычно 6–10 минут. Автоматической прогрессии по календарю нет."]}],"notes":["Жёлтый: не более min(план,15 минут), легко. Оранжевый: отдых или короткая привычная прогулка, если безопасно. Красный: отмена. Нулевой план остаётся нулевым.","Поддержка опциональна, по переносимости. Нет автоматического перехода на следующую ступень раз в три цикла."],"branches":[]}'::jsonb, '[]'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET cycle_id=EXCLUDED.cycle_id, label=EXCLUDED.label, title=EXCLUDED.title, notes=EXCLUDED.notes, sort_order=EXCLUDED.sort_order, kind=EXCLUDED.kind, cardio_zone=EXCLUDED.cardio_zone, cardio_minutes=EXCLUDED.cardio_minutes, day_in_cycle=EXCLUDED.day_in_cycle, warmup_level=EXCLUDED.warmup_level, prescription=EXCLUDED.prescription, branches=EXCLUDED.branches;
