INSERT INTO workout_exercises (workout_id, sort_order, name, weight_text, pct_of_tm, target_reps, target_sets, target_rir_min, target_rir_max, comment, rest_seconds, program_key, role, pct_min, pct_max, example_kg_min, example_kg_max, target_rpe_min, target_rpe_max, is_optional, condition_code, exclude_from_tonnage, prescription) VALUES ((SELECT id FROM workouts WHERE program_key='v4:v9-11-b4'), 1, 'Жим лёжа с паузой', '85 кг · стартовый пример при R=115', 73.91304347826086, '3', '2', NULL, NULL, 'Вес — стартовый пример при R=115, а не обязательное назначение. Фактический RPE важнее цифры.
