INSERT INTO workouts (cycle_id, label, title, notes, sort_order, kind, cardio_zone, cardio_minutes, program_key, day_in_cycle, warmup_level, prescription, branches) VALUES ((SELECT id FROM cycles WHERE program_version='h2-v9-4.0' AND program_key='v4:v9-12'), 'B3', 'Лёгкое кардио и условная поддержка', 'Жёлтый: не более min(план,15 минут), легко. Оранжевый: отдых или короткая привычная прогулка, если безопасно. Красный: отмена. Нулевой план остаётся нулевым.
Тренировочный комплекс не добавляется. Назначенный специалистом режим согласуется отдельно.', 3, 'cardio', 'Z1', '15 минут всего, очень легко, свободный разговор.', 'v4:v9-12-b3', 7, NULL, '{"id":"v9-12-b3","slot":"B3","day":7,"kind":"cardio","title":"Лёгкое кардио и условная поддержка","duration":{"min":15,"max":15},"isRestDay":false,"isDeload":false,"isTaper":true,"isControl":false,"cardio":{"zone":"Z1","warmupMinutes":0,"mainMinutes":{"min":15,"max":15},"cooldownMinutes":0,"modality":"comfortable_low_impact","prescriptionText":"15 минут всего, очень легко, свободный разговор."},"warmupLevel":null,"exercises":[],"notes":["Жёлтый: не более min(план,15 минут), легко. Оранжевый: отдых или короткая привычная прогулка, если безопасно. Красный: отмена. Нулевой план остаётся нулевым.","Тренировочный комплекс не добавляется. Назначенный специалистом режим согласуется отдельно."],"branches":[]}'::jsonb, '[]'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET cycle_id=EXCLUDED.cycle_id, label=EXCLUDED.label, title=EXCLUDED.title, notes=EXCLUDED.notes, sort_order=EXCLUDED.sort_order, kind=EXCLUDED.kind, cardio_zone=EXCLUDED.cardio_zone, cardio_minutes=EXCLUDED.cardio_minutes, day_in_cycle=EXCLUDED.day_in_cycle, warmup_level=EXCLUDED.warmup_level, prescription=EXCLUDED.prescription, branches=EXCLUDED.branches;
INSERT INTO workouts (cycle_id, label, title, notes, sort_order, kind, cardio_zone, cardio_minutes, program_key, day_in_cycle, warmup_level, prescription, branches) VALUES ((SELECT id FROM cycles WHERE program_version='h2-v9-4.0' AND program_key='v4:v9-12'), 'B4', 'Зал B · Тейпер II', 'Главное — убрать усталость. В зале B за 4 дня до теста только лёгкая техника; дополнительной грудной работы нет.
Сначала симптомы/седация, затем готовность, страховка и разминка. Никаких автоматических медицинских уровней по проценту.
RPE — фактическая оценка запаса, не прогноз из килограммов. Разминка строится от выбранного рабочего веса и не превышает личного предела.
