-- v9-13 Итоговый замер
INSERT INTO cycles (number, name, macrocycle, notes, sort_order, block, program_version, program_key, day_offset, checkpoint, rules) VALUES (13, 'Итоговый замер', 5, 'Тест — возможность измерить прогресс, не обязанность. День 171 действительно свободен от тренировочного комплекса.

Не догонять пропущенное. При необходимости смещать календарь без уплотнения жимовых дней.

Пересмотреть программу после 2–3 циклов по реальному журналу.', 22, 'v9', 'h2-v9-4.0', 'v4:v9-13', 168, '{"id":"v9-13-control","type":"final_triple","programDay":172}'::jsonb, '["Не догонять пропущенное. При необходимости смещать календарь без уплотнения жимовых дней.","Пересмотреть программу после 2–3 циклов по реальному журналу."]'::jsonb) ON CONFLICT (program_version, program_key) WHERE program_key IS NOT NULL DO UPDATE SET number=EXCLUDED.number, name=EXCLUDED.name, macrocycle=EXCLUDED.macrocycle, notes=EXCLUDED.notes, sort_order=EXCLUDED.sort_order, block=EXCLUDED.block, day_offset=EXCLUDED.day_offset, checkpoint=EXCLUDED.checkpoint, rules=EXCLUDED.rules;
INSERT INTO workouts (cycle_id, label, title, notes, sort_order, kind, cardio_zone, cardio_minutes, program_key, day_in_cycle, warmup_level, prescription, branches) VALUES ((SELECT id FROM cycles WHERE program_version='h2-v9-4.0' AND program_key='v4:v9-13'), 'B1', 'Полный тренировочный отдых', 'День 171: полный тренировочный отдых. Привычная бытовая активность без утомления.
Тренировочный комплекс не добавляется. Назначенный специалистом режим согласуется отдельно.', 1, 'cardio', NULL, '0 минут кардио; 0 тренировочных подходов. Назначения врача самостоятельно не отменять.', 'v4:v9-13-b1', 3, NULL, '{"id":"v9-13-b1","slot":"B1","day":3,"kind":"cardio","title":"Полный тренировочный отдых","duration":{"min":0,"max":0},"isRestDay":true,"isDeload":false,"isTaper":true,"isControl":false,"cardio":{"zone":null,"warmupMinutes":0,"mainMinutes":{"min":0,"max":0},"cooldownMinutes":0,"modality":"comfortable_low_impact","prescriptionText":"0 минут кардио; 0 тренировочных подходов. Назначения врача самостоятельно не отменять."},"warmupLevel":null,"exercises":[],"notes":["День 171: полный тренировочный отдых. Привычная бытовая активность без утомления.","Тренировочный комплекс не добавляется. Назначенный специалистом режим согласуется отдельно."],"branches":[]}'::jsonb, '[]'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET cycle_id=EXCLUDED.cycle_id, label=EXCLUDED.label, title=EXCLUDED.title, notes=EXCLUDED.notes, sort_order=EXCLUDED.sort_order, kind=EXCLUDED.kind, cardio_zone=EXCLUDED.cardio_zone, cardio_minutes=EXCLUDED.cardio_minutes, day_in_cycle=EXCLUDED.day_in_cycle, warmup_level=EXCLUDED.warmup_level, prescription=EXCLUDED.prescription, branches=EXCLUDED.branches;
INSERT INTO workouts (cycle_id, label, title, notes, sort_order, kind, cardio_zone, cardio_minutes, program_key, day_in_cycle, warmup_level, prescription, branches) VALUES ((SELECT id FROM cycles WHERE program_version='h2-v9-4.0' AND program_key='v4:v9-13'), 'B2', 'Зал A · Итоговый замер', 'Тест — возможность измерить прогресс, не обязанность. День 171 действительно свободен от тренировочного комплекса.
Сначала симптомы/седация, затем готовность, страховка и разминка. Никаких автоматических медицинских уровней по проценту.
Контроль: одна тройка. При утомлении КТ пропускается без компенсации. После штатной 3@8 — только напечатанные лёгкие сеты; после итогового теста подсобки нет.
При нехватке времени: основной жим с полноценным отдыхом → одна тяга → остальная подсобка → необязательная ОФП.', 2, 'strength', NULL, NULL, 'v4:v9-13-b2', 4, 'control', '{"id":"v9-13-b2","slot":"B2","day":4,"kind":"strength","title":"Зал A · Итоговый замер","duration":{"min":35,"max":55},"isRestDay":false,"isDeload":false,"isTaper":true,"isControl":true,"cardio":null,"warmupLevel":"control","exercises":[{"id":"v9-13-b2-control_triple","key":"control_triple","name":"Контрольная тройка · жим с паузой","sets":"1","reps":"3","role":"test_triple","percent":null,"exampleKg":null,"targetRpe":{"min":8,"max":8},"targetRir":null,"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":300,"notes":["Одна тройка; фактический RPE записывается без подгонки к восьми. Не повторять ради попадания в число.","Без недавней подтверждённой базы — знакомый консервативный вес на 3 повтора при RPE 6–7; не автоматические 100 кг.","Если ограничение не позволяет 3@8 — согласованный фиксированный вес, без пересчёта в максимум."],"afterControlLight":false,"progressionEligible":false}],"notes":["Тест — возможность измерить прогресс, не обязанность. День 171 действительно свободен от тренировочного комплекса.","Сначала симптомы/седация, затем готовность, страховка и разминка. Никаких автоматических медицинских уровней по проценту.","Контроль: одна тройка. При утомлении КТ пропускается без компенсации. После штатной 3@8 — только напечатанные лёгкие сеты; после итогового теста подсобки нет.","При нехватке времени: основной жим с полноценным отдыхом → одна тяга → остальная подсобка → необязательная ОФП."],"branches":[{"id":"triple","default":true,"name":"Основная ветка · контрольная тройка","exercises":[]},{"id":"direct_1rm","default":false,"name":"Отдельная подготовка к 1ПМ","conditions":["Отдельно согласованные усилие и натуживание, опыт, страховка и понятная спортивная цель.","Решение до цикла 17; подтверждение или отмена на КТ4. Замена, не добавление к основной строке.","Нет синглов в Ц17/19 или были проблемы — не пробовать первый максимум в день 172."],"exercises":[{"id":"v9-13-b2-direct_0","key":"direct_0","name":"Отдельный тест 1ПМ · до трёх попыток","sets":"3","reps":"1","role":"direct_1rm","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":null,"optional":true,"condition":null,"excludeFromTonnage":false,"restSeconds":360,"notes":["Только вместо основной жимовой строки; общий индивидуальный предел сохраняется.","До 3 попыток. Первая — уверенный знакомый вес; после неудачи, гриндера, симптомов или потери контроля новых попыток нет."],"branchId":"direct_1rm"}]}]}'::jsonb, '[{"id":"triple","default":true,"name":"Основная ветка · контрольная тройка","exercises":[]},{"id":"direct_1rm","default":false,"name":"Отдельная подготовка к 1ПМ","conditions":["Отдельно согласованные усилие и натуживание, опыт, страховка и понятная спортивная цель.","Решение до цикла 17; подтверждение или отмена на КТ4. Замена, не добавление к основной строке.","Нет синглов в Ц17/19 или были проблемы — не пробовать первый максимум в день 172."],"exercises":[{"id":"v9-13-b2-direct_0","key":"direct_0","name":"Отдельный тест 1ПМ · до трёх попыток","sets":"3","reps":"1","role":"direct_1rm","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":null,"optional":true,"condition":null,"excludeFromTonnage":false,"restSeconds":360,"notes":["Только вместо основной жимовой строки; общий индивидуальный предел сохраняется.","До 3 попыток. Первая — уверенный знакомый вес; после неудачи, гриндера, симптомов или потери контроля новых попыток нет."],"branchId":"direct_1rm"}]}]'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET cycle_id=EXCLUDED.cycle_id, label=EXCLUDED.label, title=EXCLUDED.title, notes=EXCLUDED.notes, sort_order=EXCLUDED.sort_order, kind=EXCLUDED.kind, cardio_zone=EXCLUDED.cardio_zone, cardio_minutes=EXCLUDED.cardio_minutes, day_in_cycle=EXCLUDED.day_in_cycle, warmup_level=EXCLUDED.warmup_level, prescription=EXCLUDED.prescription, branches=EXCLUDED.branches;
