INSERT INTO workouts (cycle_id, label, title, notes, sort_order, kind, cardio_zone, cardio_minutes, program_key, day_in_cycle, warmup_level, prescription, branches) VALUES ((SELECT id FROM cycles WHERE program_version='h2-v9-4.0' AND program_key='v4:v9-13'), 'B3', 'Лёгкое кардио и условная поддержка', 'Жёлтый: не более min(план,15 минут), легко. Оранжевый: отдых или короткая привычная прогулка, если безопасно. Красный: отмена. Нулевой план остаётся нулевым.
Тренировочный комплекс не добавляется. Назначенный специалистом режим согласуется отдельно.', 3, 'cardio', 'Z1', '20 минут всего, очень легко, свободный разговор.', 'v4:v9-13-b3', 7, NULL, '{"id":"v9-13-b3","slot":"B3","day":7,"kind":"cardio","title":"Лёгкое кардио и условная поддержка","duration":{"min":20,"max":20},"isRestDay":false,"isDeload":false,"isTaper":true,"isControl":false,"cardio":{"zone":"Z1","warmupMinutes":0,"mainMinutes":{"min":20,"max":20},"cooldownMinutes":0,"modality":"comfortable_low_impact","prescriptionText":"20 минут всего, очень легко, свободный разговор."},"warmupLevel":null,"exercises":[],"notes":["Жёлтый: не более min(план,15 минут), легко. Оранжевый: отдых или короткая привычная прогулка, если безопасно. Красный: отмена. Нулевой план остаётся нулевым.","Тренировочный комплекс не добавляется. Назначенный специалистом режим согласуется отдельно."],"branches":[]}'::jsonb, '[]'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET cycle_id=EXCLUDED.cycle_id, label=EXCLUDED.label, title=EXCLUDED.title, notes=EXCLUDED.notes, sort_order=EXCLUDED.sort_order, kind=EXCLUDED.kind, cardio_zone=EXCLUDED.cardio_zone, cardio_minutes=EXCLUDED.cardio_minutes, day_in_cycle=EXCLUDED.day_in_cycle, warmup_level=EXCLUDED.warmup_level, prescription=EXCLUDED.prescription, branches=EXCLUDED.branches;
INSERT INTO workouts (cycle_id, label, title, notes, sort_order, kind, cardio_zone, cardio_minutes, program_key, day_in_cycle, warmup_level, prescription, branches) VALUES ((SELECT id FROM cycles WHERE program_version='h2-v9-4.0' AND program_key='v4:v9-13'), 'B4', 'Зал B · Итоговый замер', 'Тест — возможность измерить прогресс, не обязанность. День 171 действительно свободен от тренировочного комплекса.
Сначала симптомы/седация, затем готовность, страховка и разминка. Никаких автоматических медицинских уровней по проценту.
RPE — фактическая оценка запаса, не прогноз из килограммов. Разминка строится от выбранного рабочего веса и не превышает личного предела.
При нехватке времени: основной жим с полноценным отдыхом → одна тяга → остальная подсобка → необязательная ОФП.', 4, 'strength', NULL, NULL, 'v4:v9-13-b4', 8, 'light', '{"id":"v9-13-b4","slot":"B4","day":8,"kind":"strength","title":"Зал B · Итоговый замер","duration":{"min":25,"max":40},"isRestDay":false,"isDeload":false,"isTaper":true,"isControl":false,"cardio":null,"warmupLevel":"light","exercises":[{"id":"v9-13-b4-paused_bench_0","key":"paused_bench_0","name":"Жим лёжа с паузой","sets":"2","reps":"5","role":"primary_bench","percent":{"min":50,"max":50},"exampleKg":{"min":57.5,"max":57.5},"targetRpe":{"min":null,"max":6},"targetRir":null,"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":180,"notes":["Вес — стартовый пример при R=115, а не обязательное назначение. Фактический RPE важнее цифры.","До последнего сета при RPE около 7,5 снизить вес на 2,5–5 кг; при RPE 8 обычный основной жим закончить.","Одинаковое касание и пауза около секунды; без отказа и компенсации пропусков."],"afterControlLight":false,"progressionEligible":false},{"id":"v9-13-b4-lat_pulldown","key":"lat_pulldown","name":"Верхний блок","sets":"2","reps":"8–10","role":"back_accessory","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":4,"max":5},"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":90,"notes":["Вес подбирать отдельно по запасу. После двух выполнений всех сетов на верхней границе повторов с целевым RIR — минимальный шаг; затем нижняя граница повторов.","Не переносить прибавку жима на гантели или блок. При боли прекратить провоцирующее упражнение."]}],"notes":["Тест — возможность измерить прогресс, не обязанность. День 171 действительно свободен от тренировочного комплекса.","Сначала симптомы/седация, затем готовность, страховка и разминка. Никаких автоматических медицинских уровней по проценту.","RPE — фактическая оценка запаса, не прогноз из килограммов. Разминка строится от выбранного рабочего веса и не превышает личного предела.","При нехватке времени: основной жим с полноценным отдыхом → одна тяга → остальная подсобка → необязательная ОФП."],"branches":[]}'::jsonb, '[]'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET cycle_id=EXCLUDED.cycle_id, label=EXCLUDED.label, title=EXCLUDED.title, notes=EXCLUDED.notes, sort_order=EXCLUDED.sort_order, kind=EXCLUDED.kind, cardio_zone=EXCLUDED.cardio_zone, cardio_minutes=EXCLUDED.cardio_minutes, day_in_cycle=EXCLUDED.day_in_cycle, warmup_level=EXCLUDED.warmup_level, prescription=EXCLUDED.prescription, branches=EXCLUDED.branches;
INSERT INTO workout_exercises (workout_id, sort_order, name, weight_text, pct_of_tm, target_reps, target_sets, target_rir_min, target_rir_max, comment, rest_seconds, program_key, role, pct_min, pct_max, example_kg_min, example_kg_max, target_rpe_min, target_rpe_max, is_optional, condition_code, exclude_from_tonnage, prescription) VALUES ((SELECT id FROM workouts WHERE program_key='v4:v9-13-b4'), 1, 'Жим лёжа с паузой', '57.5 кг · стартовый пример при R=115', 50, '5', '2', NULL, NULL, 'Вес — стартовый пример при R=115, а не обязательное назначение. Фактический RPE важнее цифры.
До последнего сета при RPE около 7,5 снизить вес на 2,5–5 кг; при RPE 8 обычный основной жим закончить.
Одинаковое касание и пауза около секунды; без отказа и компенсации пропусков.', 180, 'v4:v9-13-b4-paused_bench_0', 'primary_bench', 50, 50, 57.5, 57.5, NULL, 6, false, NULL, false, '{"id":"v9-13-b4-paused_bench_0","key":"paused_bench_0","name":"Жим лёжа с паузой","sets":"2","reps":"5","role":"primary_bench","percent":{"min":50,"max":50},"exampleKg":{"min":57.5,"max":57.5},"targetRpe":{"min":null,"max":6},"targetRir":null,"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":180,"notes":["Вес — стартовый пример при R=115, а не обязательное назначение. Фактический RPE важнее цифры.","До последнего сета при RPE около 7,5 снизить вес на 2,5–5 кг; при RPE 8 обычный основной жим закончить.","Одинаковое касание и пауза около секунды; без отказа и компенсации пропусков."],"afterControlLight":false,"progressionEligible":false}'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET workout_id=EXCLUDED.workout_id, sort_order=EXCLUDED.sort_order, name=EXCLUDED.name, weight_text=EXCLUDED.weight_text, pct_of_tm=EXCLUDED.pct_of_tm, target_reps=EXCLUDED.target_reps, target_sets=EXCLUDED.target_sets, target_rir_min=EXCLUDED.target_rir_min, target_rir_max=EXCLUDED.target_rir_max, comment=EXCLUDED.comment, rest_seconds=EXCLUDED.rest_seconds, role=EXCLUDED.role, pct_min=EXCLUDED.pct_min, pct_max=EXCLUDED.pct_max, example_kg_min=EXCLUDED.example_kg_min, example_kg_max=EXCLUDED.example_kg_max, target_rpe_min=EXCLUDED.target_rpe_min, target_rpe_max=EXCLUDED.target_rpe_max, is_optional=EXCLUDED.is_optional, condition_code=EXCLUDED.condition_code, exclude_from_tonnage=EXCLUDED.exclude_from_tonnage, prescription=EXCLUDED.prescription;
INSERT INTO workout_exercises (workout_id, sort_order, name, weight_text, pct_of_tm, target_reps, target_sets, target_rir_min, target_rir_max, comment, rest_seconds, program_key, role, pct_min, pct_max, example_kg_min, example_kg_max, target_rpe_min, target_rpe_max, is_optional, condition_code, exclude_from_tonnage, prescription) VALUES ((SELECT id FROM workouts WHERE program_key='v4:v9-13-b4'), 2, 'Верхний блок', '4–5 RIR', NULL, '8–10', '2', 4, 5, 'Вес подбирать отдельно по запасу. После двух выполнений всех сетов на верхней границе повторов с целевым RIR — минимальный шаг; затем нижняя граница повторов.
Не переносить прибавку жима на гантели или блок. При боли прекратить провоцирующее упражнение.', 90, 'v4:v9-13-b4-lat_pulldown', 'back_accessory', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, false, '{"id":"v9-13-b4-lat_pulldown","key":"lat_pulldown","name":"Верхний блок","sets":"2","reps":"8–10","role":"back_accessory","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":4,"max":5},"optional":false,"condition":null,"excludeFromTonnage":false,"restSeconds":90,"notes":["Вес подбирать отдельно по запасу. После двух выполнений всех сетов на верхней границе повторов с целевым RIR — минимальный шаг; затем нижняя граница повторов.","Не переносить прибавку жима на гантели или блок. При боли прекратить провоцирующее упражнение."]}'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET workout_id=EXCLUDED.workout_id, sort_order=EXCLUDED.sort_order, name=EXCLUDED.name, weight_text=EXCLUDED.weight_text, pct_of_tm=EXCLUDED.pct_of_tm, target_reps=EXCLUDED.target_reps, target_sets=EXCLUDED.target_sets, target_rir_min=EXCLUDED.target_rir_min, target_rir_max=EXCLUDED.target_rir_max, comment=EXCLUDED.comment, rest_seconds=EXCLUDED.rest_seconds, role=EXCLUDED.role, pct_min=EXCLUDED.pct_min, pct_max=EXCLUDED.pct_max, example_kg_min=EXCLUDED.example_kg_min, example_kg_max=EXCLUDED.example_kg_max, target_rpe_min=EXCLUDED.target_rpe_min, target_rpe_max=EXCLUDED.target_rpe_max, is_optional=EXCLUDED.is_optional, condition_code=EXCLUDED.condition_code, exclude_from_tonnage=EXCLUDED.exclude_from_tonnage, prescription=EXCLUDED.prescription;

